-- LOCAL PRO ONLY. Private commercial-stage catalogue gateway.
-- Exact legacy mutation/result/receipt tables and payloads; no public-directory
-- prerequisite, no public booking changes, no team access or real sends.
begin;
create or replace function public.pro_lead_private_stage_catalog(p_actor uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select pro_lead_origin_stage_catalog(p_actor)$$;
create or replace function public.pro_lead_private_stage_pipeline_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_request_pipeline_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_request_pipeline_actions where owner_id=p_actor and action_id=p_action;if not found or not coalesce(r.input->>'action'in('stage_save','stage_reorder','stage_visibility','stage_retire'),false)then return jsonb_build_object('receipt',null);end if;if r.input?'requestId' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=(r.input->>'requestId')::uuid) then raise exception 'Request unavailable' using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_private_stage_pipeline_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare act text;aid uuid;sid text;rid uuid;expected text[];catalog_revision integer;current_revision integer;state_revision integer;catalog jsonb;old_catalog jsonb;before_json jsonb;after_json jsonb;answer jsonb;lead jsonb;auto jsonb;target text;stage_row pro_request_pipeline_stages;ref pro_request_pipeline_states;receipt pro_request_pipeline_actions;position_value integer;reassigned integer:=0;before_name text;after_name text;builtin_order text[];ids text[];begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid pipeline operation' using errcode='22023';end if;
 act:=p_input->>'action';if act not in('stage_save','stage_reorder','stage_visibility','stage_retire')then raise exception'Only catalogue actions belong to this gateway'using errcode='22023';end if;aid:=(p_input->>'actionId')::uuid;catalog_revision:=(p_input->>'catalogRevision')::integer;
 expected:=case act when 'stage_save' then array['action','actionId','catalogRevision','name','stageId'] when 'stage_reorder' then array['action','actionId','catalogRevision','stageIds'] when 'stage_visibility' then array['action','actionId','catalogRevision','hidden','reassignToId','stageId'] when 'stage_retire' then array['action','actionId','catalogRevision','reassignToId','stageId'] when 'set_stage' then array['action','actionId','catalogRevision','requestId','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','requestId','revision'] else null end;
 if expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or aid is null then raise exception 'Unexpected pipeline fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then if receipt.input is distinct from p_input then raise exception 'Pipeline action reused' using errcode='22023';end if;perform pro_lead_private_stage_pipeline_action_read(p_actor,aid);return receipt.result;end if;
 old_catalog:=pro_lead_private_stage_catalog(p_actor);current_revision:=(old_catalog->>'revision')::integer;if current_revision<>catalog_revision then raise exception 'Lead stages changed' using errcode='40001';end if;
 -- Materialize defaults only on an explicit mutation. Reads never backfill.
 insert into pro_request_pipeline_heads values(p_actor,0) on conflict do nothing;
 insert into pro_request_pipeline_stages(owner_id,id,position) select p_actor,v,(n-1)::integer from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n) on conflict do nothing;
 if act in('set_stage','return_auto') then
  if jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid request state' using errcode='22023';end if;
  rid:=(p_input->>'requestId')::uuid;if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=rid) then raise exception 'Request unavailable' using errcode='42501';end if;
  before_json:=pro_request_pipeline_state(p_actor,rid);state_revision:=(before_json->>'revision')::integer;if state_revision<>(p_input->>'revision')::integer then raise exception 'Commercial stage changed' using errcode='40001';end if;
  if act='set_stage' then sid:=p_input->>'stageId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired;if not found then raise exception 'Choose an active stage' using errcode='40001';end if;
  else sid:=null;end if;
  select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->>'stageId';
  insert into pro_request_pipeline_states(owner_id,request_id,mode,stage_id,revision) values(p_actor,rid,case when act='set_stage' then 'manual' else 'automatic' end,sid,state_revision+1) on conflict(owner_id,request_id) do update set mode=excluded.mode,stage_id=excluded.stage_id,revision=excluded.revision,updated_at=now();
  after_json:=pro_request_pipeline_state(p_actor,rid);lead:=pro_lead_origin_request(p_actor,rid);catalog:=pro_lead_private_stage_catalog(p_actor);select value into auto from jsonb_array_elements(catalog->'stages') where value->>'id'=lead->>'effectiveStageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
  insert into pro_request_pipeline_history values(p_actor,rid,aid,act,before_json,after_json,before_name,after_name,now());answer:=jsonb_build_object('action',act,'catalogRevision',current_revision,'state',after_json,'before',before_json,'stage',auto,'evidence',lead->'evidence');
 else
  if current_revision>=2147483647 then raise exception 'Stage catalogue revision exhausted' using errcode='40001';end if;
  if act='stage_save' then
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 25 or p_input->>'name'~'[[:cntrl:]]' then raise exception 'Invalid custom stage' using errcode='22023';end if;
   sid:=((p_input->>'stageId')::uuid)::text;select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
   if found then if stage_row.retired then raise exception 'Retired stage identity cannot be reused' using errcode='40001';end if;update pro_request_pipeline_stages set name=btrim(p_input->>'name') where owner_id=p_actor and id=sid;
   else if(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired and name is not null)>=12 then raise exception 'Twelve custom stages maximum' using errcode='40001';end if;select count(*) into position_value from pro_request_pipeline_stages where owner_id=p_actor and not retired;insert into pro_request_pipeline_stages(owner_id,id,name,position) values(p_actor,sid,btrim(p_input->>'name'),position_value);end if;
  elsif act='stage_reorder' then
   if jsonb_typeof(p_input->'stageIds') is distinct from 'array' or jsonb_array_length(p_input->'stageIds') not between 6 and 18 or exists(select 1 from jsonb_array_elements(p_input->'stageIds')x where jsonb_typeof(x)<>'string') then raise exception 'Invalid stage order' using errcode='22023';end if;
   select array_agg(value order by ord) into ids from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord);select array_agg(value order by ord) into builtin_order from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord) where value in('new','followed_up','connected','meeting_scheduled','estimate_sent','won');
   if builtin_order is distinct from array['new','followed_up','connected','meeting_scheduled','estimate_sent','won'] or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or cardinality(ids)<>(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired) or exists(select 1 from unnest(ids)x where not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=x and not retired)) then raise exception 'Stage order changed' using errcode='40001';end if;
   update pro_request_pipeline_stages s set position=x.ord-1 from unnest(ids)with ordinality x(id,ord) where s.owner_id=p_actor and s.id=x.id;
  else
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'reassignToId') not in('string','null') then raise exception 'Invalid stage visibility' using errcode='22023';end if;
   sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not retired;if not found then raise exception 'Stage unavailable' using errcode='40001';end if;
   if act='stage_retire' then if stage_row.name is null then raise exception 'Built-in stages cannot be retired' using errcode='22023';end if;
   elsif jsonb_typeof(p_input->'hidden') is distinct from 'boolean' or(p_input->>'hidden')::boolean=stage_row.hidden or sid in('new','won') and(p_input->>'hidden')::boolean then raise exception 'Invalid stage visibility transition' using errcode='22023';end if;
   if act='stage_retire' or(p_input->>'hidden')::boolean then
    if target is null or target=sid or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=target and not hidden and not retired) then raise exception 'Choose a visible replacement stage' using errcode='40001';end if;
    select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
    for ref in select * from pro_request_pipeline_states where owner_id=p_actor and mode='manual' and stage_id=sid order by request_id for update loop
     if ref.revision>=2147483647 then raise exception 'Request stage revision exhausted' using errcode='40001';end if;before_json:=pro_request_pipeline_state(p_actor,ref.request_id);update pro_request_pipeline_states set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=ref.request_id;after_json:=pro_request_pipeline_state(p_actor,ref.request_id);insert into pro_request_pipeline_history values(p_actor,ref.request_id,aid,'reassign_stage',before_json,after_json,stage_row.name,after_name,now());reassigned:=reassigned+1;
    end loop;
    update pro_request_pipeline_stages set reassign_to_id=target where owner_id=p_actor and hidden and reassign_to_id=sid;
    update pro_request_pipeline_stages set hidden=true,reassign_to_id=target,retired=(act='stage_retire') where owner_id=p_actor and id=sid;
    if act='stage_retire' then with ordered as(select id,row_number()over(order by position)-1 pos from pro_request_pipeline_stages where owner_id=p_actor and not retired)update pro_request_pipeline_stages s set position=o.pos from ordered o where s.owner_id=p_actor and s.id=o.id;end if;
   else if target is not null then raise exception 'Showing a stage needs no reassignment' using errcode='22023';end if;update pro_request_pipeline_stages set hidden=false,reassign_to_id=null where owner_id=p_actor and id=sid;end if;
  end if;
  update pro_request_pipeline_heads set revision=current_revision+1 where owner_id=p_actor;catalog:=pro_lead_private_stage_catalog(p_actor);answer:=jsonb_build_object('action',act,'catalog',catalog,'reassigned',reassigned);
 end if;
 perform pro_lead_origin_owner(p_actor);insert into pro_request_pipeline_actions(owner_id,action_id,input,result,actor_name) values(p_actor,aid,p_input,answer,pro_team_name(p_actor));perform pro_lead_origin_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_private_stage_read_action(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_catalog_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=p_action;if found then if not coalesce(r.input->>'action'in('stage_save','stage_reorder','stage_visibility','stage_retire'),false)then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end if;return pro_lead_private_stage_pipeline_action_read(p_actor,p_action);end $$;
create or replace function public.pro_lead_private_stage_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;act text;sid text;target text;r pro_lead_center_catalog_actions;old_receipt pro_request_pipeline_actions;ref pro_lead_center_records;answer jsonb;before_json jsonb;after_json jsonb;before_name text;after_name text;moved integer:=0;begin
 perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'then raise exception'Invalid catalogue action'using errcode='22023';end if;aid:=(p_input->>'actionId')::uuid;act:=p_input->>'action';if aid is null or act is null or act not in('stage_save','stage_reorder','stage_visibility','stage_retire') then raise exception 'Invalid catalogue action' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;return r.result;end if;
 if exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_creates where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_actions where owner_id=p_actor and action_id=aid)then raise exception 'Action identity already used' using errcode='40001';end if;
 select * into old_receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then
  if old_receipt.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;
  if exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and created_at<=old_receipt.at) then raise exception 'Legacy catalogue result cannot establish mixed provenance' using errcode='40001';end if;
  insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,old_receipt.result,pro_team_name(p_actor),true,now());perform pro_lead_origin_owner(p_actor);return old_receipt.result;
 end if;
 sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
 perform set_config('pro.lead_center_catalog',p_actor::text||':'||aid::text,true);answer:=pro_lead_private_stage_pipeline_mutate(p_actor,p_input);
 if act='stage_retire' or act='stage_visibility' and(p_input->>'hidden')::boolean then
  for ref in select * from pro_lead_center_records where owner_id=p_actor and kind='manual' and stage_mode='manual' and stage_id=sid order by id for update loop
   if ref.revision>=2147483647 then raise exception 'Opportunity revision exhausted' using errcode='40001';end if;before_json:=pro_lead_origin_item(p_actor,'manual',ref.id);update pro_lead_center_records set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=ref.id;after_json:=pro_lead_origin_item(p_actor,'manual',ref.id);insert into pro_lead_center_history values(p_actor,'manual',ref.id,aid,'reassign_stage',before_json,after_json,before_name,after_name,now());moved:=moved+1;
  end loop;
 end if;
 perform set_config('pro.lead_center_catalog','',true);answer:=jsonb_set(answer,'{reassigned}',to_jsonb((answer->>'reassigned')::integer+moved));insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,answer,pro_team_name(p_actor),false,now());perform pro_lead_origin_owner(p_actor);return answer;end $$;
-- No table, column, index, trigger or old function definition is changed.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_private_stage_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
